    if (!n) continue;
    // Skip nodes that belong to footway roads; assume a string member `road_type`
    if (n->road_type == "footway") continue;
    float dx = n->x - x;
    float dy = n->y - y;
    float dist2 = dx * dx + dy * dy;
    if (dist2 < bestDist) {
        bestDist = dist2;
        bestNode = n;
    }
}
